function getNoZeroIntegers(n) {
  const isNoZero = (value) => !String(value).includes('0');

  for (let a = 1; a < n; a++) {
    const b = n - a;
    if (isNoZero(a) && isNoZero(b)) {
      return [a, b];
    }
  }
