function getNoZeroIntegers(n) {
  const digitsOk = (x) => {
    while (x > 0) {
      if (x % 10 === 0) return false;
      x = Math.floor(x / 10);
    }
    return true;
  };
  for (let b = n - 1; b >= 1; b--) if (digitsOk(b) && digitsOk(n - b)) return [n - b, b];
  return [];
}

